class Solution:
    def numDupDigitsAtMostN(self, n: int) -> int:
        ans = 0
        for x in range(1, n + 1):
            seen = set()
            ok = False
            while x > 0:
                d = x % 10
                if d in seen:
                    ok = True
                    break
                seen.add(d)
                x //= 10
            if ok:
                ans += 1
        return ans

