class Solution {
public:
    int numDupDigitsAtMostN(int n) {
        long long ans = 0;
        for (long long x = 1; x <= n; ++x) {
            bool seen[10] = {false};
            bool dup = false;
            long long v = x;
            while (v > 0) {
                int d = v % 10;
                if (seen[d]) { dup = true; break; }
                seen[d] = true;
                v /= 10;
            }
            if (dup) ++ans;
        }
        return (int)ans;
    }
};

