class Solution:
    def numDupDigitsAtMostN(self, n: int) -> int:
        s = str(n)
        L = len(s)
        def perm(m, k):
            r = 1
            for _ in range(k):
                r *= m
                m -= 1
            return r
        total = sum(9 * perm(9, d - 1) for d in range(1, L))
        used = set()
        for i, ch in enumerate(s):
            lo = 1 if i == 0 else 0
            for d in range(lo, int(ch)):
                if d not in used:
                    total += perm(10 - len(used) - 1, L - i - 1)
            if int(ch) in used:
                break
            used.add(int(ch))
        else:
            total += 1
        return n - total

