class Solution {
public:
    int numDupDigitsAtMostN(int n) {
        string s = to_string(n);
        int L = s.size();
        auto perm = [](int m, int k) {
            long long r = 1;
            for (int i = 0; i < k; ++i) r *= (m - i);
            return r;
        };
        long long total = 0;
        for (int d = 1; d < L; ++d) total += 9LL * perm(9, d - 1);
        bool used[10] = {false};
        int cntUsed = 0;
        for (int i = 0; i < L; ++i) {
            int cur = s[i] - '0';
            for (int d = (i == 0 ? 1 : 0); d < cur; ++d)
                if (!used[d]) total += perm(10 - cntUsed - 1, L - i - 1);
            if (used[cur]) break;
            used[cur] = true;
            cntUsed++;
            if (i == L - 1) total += 1;
        }
        return (int)(n - total);
    }
};

