    public int numDupDigitsAtMostN(int n) {
        String s = Integer.toString(n);
        int L = s.length();
        java.util.function.BiFunction<Integer, Integer, Long> perm =
            (m, k) -> { long r = 1; for (int i = 0; i < k; i++) r *= (m - i); return r; };
        long total = 0;
        for (int d = 1; d < L; d++) total += 9L * perm.apply(9, d - 1);
        boolean[] used = new boolean[10];
        int cntUsed = 0;
        for (int i = 0; i < L; i++) {
            int cur = s.charAt(i) - '0';
            for (int d = (i == 0 ? 1 : 0); d < cur; d++)
                if (!used[d]) total += perm.apply(10 - cntUsed - 1, L - i - 1);
            if (used[cur]) break;
            used[cur] = true;
            cntUsed++;
            if (i == L - 1) total += 1;
        }
        return (int)(n - total);
    }
}

